<?php declare(strict_types=1);$tour=TourInfo::effective($product,$variant);$duration=$en?($tour['durationEn'] ?? ''):($tour['duration'] ?? '');if($en&&$duration==='')$duration=$tour['duration'] ?? ''; ?>
<?php if($duration!==''):?><p class="price-note"><?=$en?'Duration:':'Thời lượng:'?> <?=$e($duration)?></p><?php endif;?>
<?php if(isset($tour['minGuests'])||isset($tour['maxGuests'])):?><p class="price-note"><?=$en?'Guests per booking:':'Số khách mỗi đơn:'?> <?php if(isset($tour['minGuests'])):?><?=$en?'at least':'tối thiểu'?> <?=$e((string)$tour['minGuests'])?><?php endif;?><?php if(isset($tour['minGuests'],$tour['maxGuests'])):?> · <?php endif;?><?php if(isset($tour['maxGuests'])):?><?=$en?'up to':'tối đa'?> <?=$e((string)$tour['maxGuests'])?><?php endif;?>.</p><?php endif;?>
